import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ----------------------------------------------------------------------
# CUDA source: efficient inclusive scan (cumulative sum) along the last dim
# ----------------------------------------------------------------------
cuda_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

#ifndef CHECK
#define CHECK(x) TORCH_CHECK(x, #x)
#endif

// block size must be a power of two and <= 1024
constexpr int BLOCK_SIZE = 256;

// Inclusive scan of a single row (length = len).
// Input and output are half precision, accumulation is done in float.
__global__ void cumsum_kernel(const __half* __restrict__ in,
                              __half* __restrict__ out,
                              const int64_t rows,
                              const int64_t len) {
    const int64_t row = blockIdx.x;
    if (row >= rows) return;

    const int tid = threadIdx.x;
    const int stride = blockDim.x;

    // pointers to the beginning of this row
    const __half* in_row  = in  + row * len;
    __half*       out_row = out + row * len;

    // ------------------------------------------------------------------
    // First pass: each thread computes the sum of its own chunk.
    // ------------------------------------------------------------------
    float thread_sum = 0.0f;
    for (int64_t i = tid; i < len; i += stride) {
        thread_sum += __half2float(in_row[i]);
    }

    // Store per‑thread partial sums in shared memory.
    extern __shared__ float sh[];
    sh[tid] = thread_sum;
    __syncthreads();

    // ------------------------------------------------------------------
    // Inclusive scan over the per‑thread partial sums (Blelloch style).
    // The algorithm works for any power‑of‑two BLOCK_SIZE.
    // ------------------------------------------------------------------
    for (int offset = 1; offset < BLOCK_SIZE; offset <<= 1) {
        float val = 0.0f;
        if (tid >= offset) {
            val = sh[tid - offset];
        }
        __syncthreads();
        sh[tid] += val;
        __syncthreads();
    }

    // Offset that must be added to every element processed by this thread.
    float offset = (tid == 0) ? 0.0f : sh[tid - 1];

    // ------------------------------------------------------------------
    // Second pass: write the inclusive scan results.
    // ------------------------------------------------------------------
    float running = offset;
    for (int64_t i = tid; i < len; i += stride) {
        running += __half2float(in_row[i]);
        out_row[i] = __float2half(running);
    }
}

// ----------------------------------------------------------------------
// Wrapper called from Python
// ----------------------------------------------------------------------
torch::Tensor cumsum_cuda(torch::Tensor input, int64_t dim) {
    CHECK(input.is_cuda());
    CHECK(input.is_contiguous());
    CHECK(input.dtype() == torch::kFloat16);

    // Move the scan dimension to the last position.
    const int64_t ndims = input.dim();
    int64_t dim_adj = dim >= 0 ? dim : dim + ndims;
    std::vector<int64_t> perm;
    perm.reserve(ndims);
    for (int64_t i = 0; i < ndims; ++i) perm.push_back(i);
    perm.erase(perm.begin() + dim_adj);
    perm.push_back(dim_adj);
    torch::Tensor x_perm = input.permute(perm).contiguous();

    // Collapse all leading dims into a single outer dimension.
    const int64_t outer = x_perm.numel() / x_perm.size(-1);
    const int64_t len   = x_perm.size(-1);
    torch::Tensor x_2d = x_perm.view({outer, len});

    torch::Tensor out_2d = torch::empty_like(x_2d);

    const dim3 block(BLOCK_SIZE);
    const dim3 grid(outer);
    const size_t shared_bytes = BLOCK_SIZE * sizeof(float);

    cumsum_kernel<<<grid, block, shared_bytes, at::cuda::getCurrentCUDAStream()>>>(
        x_2d.data_ptr<at::Half>(),
        out_2d.data_ptr<at::Half>(),
        outer,
        len
    );

    // Restore original shape and permutation.
    torch::Tensor out_perm = out_2d.view_as(x_perm);
    std::vector<int64_t> inv_perm(ndims);
    for (int64_t i = 0; i < ndims; ++i) inv_perm[perm[i]] = i;
    return out_perm.permute(inv_perm);
}
"""

